-- Rides dataset: a ride-hailing service (riders, drivers, trips, payments, ratings).

PRAGMA foreign_keys = ON;


CREATE TABLE riders (
  rider_id    INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  city        TEXT NOT NULL,
  signup_date DATE NOT NULL
);
CREATE TABLE drivers (
  driver_id    INTEGER PRIMARY KEY,
  name         TEXT NOT NULL,
  city         TEXT NOT NULL,
  joined_on    DATE NOT NULL,
  vehicle_type TEXT NOT NULL CHECK (vehicle_type IN ('economy','comfort','xl')),
  status       TEXT NOT NULL CHECK (status IN ('active','inactive'))
);
CREATE TABLE trips (
  trip_id          INTEGER PRIMARY KEY,
  rider_id         INTEGER NOT NULL REFERENCES riders(rider_id),
  driver_id        INTEGER NOT NULL REFERENCES drivers(driver_id),
  city             TEXT NOT NULL,
  requested_at     DATETIME NOT NULL,
  pickup_at        DATETIME,
  dropoff_at       DATETIME,
  distance_km      REAL,
  fare             REAL,
  surge_multiplier REAL NOT NULL DEFAULT 1.0,
  status           TEXT NOT NULL CHECK (status IN ('completed','cancelled_by_rider','cancelled_by_driver','no_show'))
);
CREATE TABLE payments (
  payment_id INTEGER PRIMARY KEY,
  trip_id    INTEGER NOT NULL REFERENCES trips(trip_id),
  method     TEXT NOT NULL CHECK (method IN ('card','wallet','cash')),
  amount     REAL NOT NULL,
  tip        REAL NOT NULL DEFAULT 0,
  paid_at    DATETIME NOT NULL,
  status     TEXT NOT NULL CHECK (status IN ('succeeded','failed','refunded'))
);
CREATE TABLE ratings (
  trip_id      INTEGER PRIMARY KEY REFERENCES trips(trip_id),
  driver_stars INTEGER CHECK (driver_stars BETWEEN 1 AND 5),
  rider_stars  INTEGER CHECK (rider_stars BETWEEN 1 AND 5),
  comment      TEXT
);





